// launch-factory: 셀프 탈퇴·내 정보 내려받기·파기 조립. 흐름은 @launch-factory/account-lifecycle 이 갖는다:
//   탈퇴 요청 = 살아 있는 구독을 먼저 기간 끝 해지 → 유예(기본 7일) 기록 → 세션 전부 끊기. 유예 중 다시 로그인하면 취소된다(인증 항목의 로그인 훅).
//   파기 Cron = 유예가 지난 요청을 잡아 구독 즉시 해지 → 개인 식별 정보 삭제(거래기록은 가명 참조로 분리 보존) → 계측 삭제.
import { authAdapter, isPlaceholderEmail, type LaunchAuthPort } from "@launch-factory/auth"
import { exportMyData, NO_ANALYTICS_ERASER, requestAccountDeletion, runPurge, type AnalyticsEraser, type PurgeReport } from "@launch-factory/account-lifecycle"
import { postHogEraser } from "@launch-factory/analytics-posthog/erase"
import { user } from "@launch-factory/db"
import { authEmails } from "@launch-factory/email"
import { eq } from "drizzle-orm"
import { authIO, getAuth } from "@/lib/launch/auth"
import { billingPorts } from "@/lib/launch/account-billing"
import { appUrl, DEFAULT_LOCALE, PRODUCT_NAME } from "@/lib/launch/config"
import { database } from "@/lib/launch/db"
import { env, optional, required } from "@/lib/launch/env"
import { mailer } from "@/lib/launch/mailer"

/**
 * 탈퇴 접수 메일(D09). 새 요청일 때만 보낸다(두 번 눌러도 한 통). 메일이 실패해도 탈퇴는 이미 기록됐다 — 던지지 않고 이름만 로그로 남긴다(주소가 섞일 수 있어 메시지는 싣지 않는다).
 * 대체 주소(카카오 이메일 없는 계정)로는 보낼 수 없어 건너뛴다.
 */
async function sendDeletionReceipt(userId: string, graceUntil: string): Promise<void> {
  try {
    const [u] = await (await database()).select({ email: user.email, name: user.name, locale: user.locale, timeZone: user.timeZone }).from(user).where(eq(user.id, userId)).limit(1)
    if (!u || isPlaceholderEmail(u.email)) return
    await authEmails(mailer(), { productName: PRODUCT_NAME, defaultLocale: DEFAULT_LOCALE }).accountDeletionRequested(
      u.email,
      { graceUntil, signInUrl: `${appUrl()}/sign-in` },
      { name: u.name, locale: u.locale, timeZone: u.timeZone },
    )
  } catch (e) {
    console.error(`[account] deletion receipt email failed: ${e instanceof Error ? e.name : "unknown"}`)
  }
}

/** 탈퇴·내려받기가 켜진 인증 포트(서버 액션용). 결제 포트는 탈퇴를 요청할 때 처음 만든다 — 내려받기는 결제 키 없이도 된다 */
export async function accountPort(): Promise<LaunchAuthPort> {
  const db = await database()
  return authAdapter(await getAuth(), await authIO(), {
    callbackURL: "/",
    locale: DEFAULT_LOCALE,
    account: {
      requestDeletion: async (userId) => {
        const r = await requestAccountDeletion({ db, billingFor: await billingPorts() }, userId)
        if (r.ok && !r.alreadyRequested) await sendDeletionReceipt(userId, r.graceUntil)
        return r
      },
      exportData: (userId) => exportMyData(db, userId),
    },
  })
}

/**
 * live 는 PostHog 사람·이벤트·녹화를 지운다(개인 API 키). mock 은 지우지 않는다(계측 공급자가 없다).
 * 분석은 선택이다(LFOBS): POSTHOG_HOST·지움 키가 모두 없으면 분석을 켠 적이 없다 — PostHog 에 쌓인 것이 없어 지울 것이 없다(DB 파기는 그대로 돈다).
 * 일부만 있으면 지울 수 없는 상태다 — 던져서 파기 Cron 전체를 멈추지 않고, 지움 단계가 「분석 지움 실패」로 남아 계속 다시 시도하게 한다(빠진 이름만 알린다).
 */
export function analyticsEraser(): AnalyticsEraser {
  if (env().LF_MODE !== "live") return NO_ANALYTICS_ERASER
  const host = optional("POSTHOG_HOST")
  const personalApiKey = optional("POSTHOG_PERSONAL_API_KEY")
  const projectId = optional("POSTHOG_PROJECT_ID")
  if (!host && !personalApiKey && !projectId) return NO_ANALYTICS_ERASER
  const missing = Object.entries({ POSTHOG_HOST: host, POSTHOG_PERSONAL_API_KEY: personalApiKey, POSTHOG_PROJECT_ID: projectId }).filter(([, v]) => !v).map(([n]) => n)
  if (missing.length) {
    return {
      erase: async () => {
        throw Object.assign(new Error(`PostHog erase is not configured: ${missing.join(", ")} is not set (see .env.example)`), { code: "not_configured" })
      },
    }
  }
  return postHogEraser({ personalApiKey: required("POSTHOG_PERSONAL_API_KEY"), projectId: required("POSTHOG_PROJECT_ID"), host: required("POSTHOG_HOST") })
}

/** 파기 Cron 본체. SUBJECT_REF_KEY(32자 이상)로 거래기록의 가명 참조를 만든다 — 바꾸면 이미 남긴 기록을 이메일로 찾을 수 없다 */
export async function purge(): Promise<PurgeReport> {
  return runPurge({ db: await database(), billingFor: await billingPorts(), subjectKey: required("SUBJECT_REF_KEY"), analytics: analyticsEraser() })
}

// launch-factory: 탈퇴·파기가 구독을 해지할 때 쓰는 결제 포트를 고르는 자리. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
// 기본은 Paddle 이다. 다른 결제(Gumroad 등)를 쓰면 이 파일만 그 포트로 바꾼다: 사용자 id 하나로 그 사용자의 BillingPort 를 돌려주면 된다.
// 결제가 없는 제품은 구독이 없다고 답하는 포트를 돌려준다(빠뜨려서 조용히 건너뛰지 않도록 일부러 여기서 고른다).
import type { BillingPort } from "@launch-factory/contract"
import { billing } from "@/lib/launch/billing"

export async function billingPorts(): Promise<(userId: string) => BillingPort> {
  const paddle = await billing()
  return (userId) => paddle.port({ userId })
}

"use server"
// launch-factory: 탈퇴·내려받기 서버 액션. 로그인한 본인에게만 작용한다(세션에서 읽는다 — 사용자 id 를 입력으로 받지 않는다).
// deleteAccount 는 구독 해지가 실패하면 탈퇴를 기록하지 않는다(요금이 계속 나가는 채로 계정만 지우지 않는다). 성공하면 세션이 모두 끊기고 유예 끝(graceUntil)을 알려 준다.
// 두 액션 모두 사람의 확인 입력(`confirmed: true`) 없이는 실행하지 않는다(LFAX M03). 탈퇴는 화면이 받는 이메일 주소 입력(`confirmEmail`)도 서버가 다시 본다.
import { authActions } from "@launch-factory/auth"
import { DEFAULT_LOCALE } from "@/lib/launch/config"
import { accountPort } from "@/lib/launch/account"

const actions = async () => authActions(await accountPort(), { locale: DEFAULT_LOCALE })

/** 입력: { confirmed: true, confirmEmail: <지금 로그인한 이메일 주소 그대로> } — 이메일이 없는 계정은 confirmed 만 */
export async function deleteAccount(input?: { confirmed?: true; confirmEmail?: string }) {
  // 타입은 블록 props 모양(계약 포트 입력 — 확인 칸 선택). 확인 칸 검사는 런타임(authActions → requireConfirmation)이 한다
  return (await actions()).deleteAccount(input)
}

/** 내 정보 내려받기(프로필·로그인 방법·세션·구독·동의 이력·마케팅 수신·조직 멤버십·진행 중 탈퇴). 비밀번호 해시·세션 토큰·2단계 비밀은 싣지 않는다. 입력: { confirmed: true } */
export async function exportMyData(input?: { confirmed?: true }) {
  return (await actions()).exportMyData(input)
}

// launch-factory: 탈퇴 파기 Cron(하루 한 번 권장). 유예가 지난 탈퇴 요청을 파기하고, 기간이 지난 보존 거래기록·접속기록을 정리한다.
// vercel.json 에 `{ "crons": [{ "path": "/api/cron/purge", "schedule": "0 5 * * *" }] }` 를 더한다. CRON_SECRET 이 없으면 401 이다.
// 두 번 와도 안전하다(같은 요청을 한 번만 잡는다 — Vercel 은 같은 실행을 두 번 보낼 수 있다). 실패한 단계는 다음 Cron 이 이어서 한다.
import { purge } from "@/lib/launch/account"
import { cronAuthorized, unauthorized } from "@/lib/launch/cron"

export const runtime = "nodejs"
export const dynamic = "force-dynamic"

export async function GET(request: Request) {
  if (!cronAuthorized(request)) return unauthorized()
  return Response.json(await purge())
}

// launch-factory: DB 연결. mock 은 메모리 PGlite(키 없이 켜진다), live 는 DATABASE_URL(Supabase 풀러 6543 — prepared statement 끔은 패키지가 한다).
// mock 의 마이그레이션은 이 앱에 설치된 db/migrations 를 쓴다(번들 안에서는 패키지 폴더를 찾을 수 없다).
import { join } from "node:path"
import { db, type Database } from "@launch-factory/db"
import { env, required } from "@/lib/launch/env"

let cached: Promise<Database> | undefined

export function database(): Promise<Database> {
  return (cached ??= env().LF_MODE === "mock" ? db.local({ migrationsFolder: join(process.cwd(), "db", "migrations") }) : Promise.resolve(db(required("DATABASE_URL"))))
}

// launch-factory: 환경 읽기. 이름만 다루고 값은 어디에도 남기지 않는다.
// LF_MODE 는 항상 필수다 — 없으면 켜지지 않는다(조용히 mock 으로 가지 않는다). live 에서는 공급자 키가 모두 필수다.
import { loadAppEnv, type AppEnv } from "@launch-factory/env"

let cached: AppEnv | undefined

/** 처음 부를 때 한 번 검사한다. 빠진 이름은 모두 모아 한 번에 알린다(값은 싣지 않는다). */
export function env(): AppEnv {
  return (cached ??= loadAppEnv())
}

/** 설정값·비밀값 하나를 읽는다. 없으면 이름만 담아 던진다. */
export function required(name: string): string {
  const value = (env() as Record<string, string | undefined>)[name] ?? process.env[name]
  if (!value) throw new Error(`${name} is not set (see .env.example)`)
  return value
}

/** 없어도 되는 설정값. */
export function optional(name: string): string | undefined {
  return process.env[name] || undefined
}

// launch-factory: 제품마다 고치는 값. 이 파일은 제품 것이다 — 레지스트리를 다시 받으면 덮어쓸지 묻는다.
import type { Locale } from "@launch-factory/email"
import { env, required } from "@/lib/launch/env"

export const PRODUCT_NAME = "My Product"
/** 사용자 칸(user.locale)이 비었을 때 메일·오류 문구의 언어 */
export const DEFAULT_LOCALE: Locale = "en"
/** 가입 때 동의 기록에 남길 약관·개인정보 처리방침의 판. 문서를 고치면 올린다 */
export const CONSENT_VERSIONS = { terms: "2026-09-30", privacy: "2026-09-30" }
/** 결제 메일이 가리키는 화면 경로 */
export const ROUTES = { billing: "/account/billing", acceptPriceChange: "/account/billing/price-change", decline: "/account/billing/cancel", security: "/forgot-password", contact: "/contact" }

/** 앱 주소. mock 에서는 로컬 주소로 켜지고, live 에서는 NEXT_PUBLIC_APP_URL 이 필수다 */
export function appUrl(): string {
  // 빈 문자열은 없는 것으로 본다 — shadcn CLI 가 envVars 이름을 `NAME=`(빈 값)으로 .env.local 에 적는다
  return process.env.NEXT_PUBLIC_APP_URL || (env().LF_MODE === "mock" ? "http://localhost:3000" : required("NEXT_PUBLIC_APP_URL"))
}

// launch-factory: Cron 경로 인증. Vercel Cron 은 CRON_SECRET 이 있으면 `Authorization: Bearer <값>` 을 붙여 부른다
// (https://vercel.com/docs/cron-jobs/manage-cron-jobs#securing-cron-jobs). 값이 없거나 다르면 거절한다 — 비밀이 없으면 열어 두지 않는다.
import { timingSafeEqual } from "node:crypto"

export function cronAuthorized(request: Request): boolean {
  const secret = process.env.CRON_SECRET
  if (!secret) return false
  const given = request.headers.get("authorization") ?? ""
  const want = `Bearer ${secret}`
  return given.length === want.length && timingSafeEqual(Buffer.from(given), Buffer.from(want))
}

export const unauthorized = () => Response.json({ error: "unauthorized" }, { status: 401 })
